var i=`0838-sambar`;var n=`world-0838`;var a=`IN`;var s=`south-asia`;var r=4;var o=59;var d={en:`Sambar`,ua:`Самбар`};var g={en:`Sambar is a India dish made with toor dal, yellow onion, tomato, okra. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Самбар, страва кухні країни Індія. Основні складники: тур дал, жовта цибуля, помідор, бамія. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`toor-dal`,300,`g`],[`water`,1050,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,160,`g`],[`tomato`,280,`g`],[`okra`,170,`g`],[`carrot`,160,`g`],[`sambar-powder`,20,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`tamarind-concentrate`,35,`g`],[`water`,250,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 4 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 4 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:4,i:[[`mustard-seeds`,7,`g`],[`fresh-curry-leaves`,12,`leaf`],[`ghee`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,15,`g`]]}];var m={slug:i,id:n,country:`IN`,region:s,servings:4,minutes:59,title:d,text:g,steps:l};export{a as country,m as default,n as id,o as minutes,s as region,r as servings,i as slug,l as steps,g as text,d as title};